    real: Callable[..., object] = record.homework_acceptance
    asked: list[bool] = []

    def reading(*args: object, **kwargs: object) -> object:
        if not asked:
            asked.append(True)
            return None
        return real(*args, **kwargs)

    monkeypatch.setattr(record, "homework_acceptance", reading)


