    if also_stores:
        says_in_order(
            answer,
            SAID_OF_ONE_ATTEMPT["some_kept"],
            SAID_OF_ONE_ATTEMPT["not_kept_for_saved"],
            SAID_OF_ONE_ATTEMPT["keep_warning"],
        )
    else:
        says_in_order(
            answer,
            SAID_OF_ONE_ATTEMPT["not_kept_for_saved"],
            SAID_OF_ONE_ATTEMPT["keep_warning"],
        )
        assert "answers were kept" not in text


