@pytest.mark.parametrize("family", ["title", "due", "destination"])
def test_a_box_or_answer_sent_twice_with_one_value_is_that_one_answer(
    tmp_path: pathlib.Path, monkeypatch: pytest.MonkeyPatch, family: str
) -> None:
    """Save with a title box, a due date box or a destination sent twice with the same value:
    one answer, so the card saves once as when it is sent once."""
    with here(open_settings(tmp_path)) as browser:
        draft_id, page = read_review(browser, monkeypatch, (RED, homework_answer()))
        page = answered(browser, draft_id, page)
        fields = page_post(page, "save", tick=units_on(page))
        name = family_field(page, fields, family)
        shown = next(value for field, value in fields if field == name)
        twice = import_review_cases.raw_post(fields, added=[(name, shown)])
        saved = followed(browser, send(browser, draft_id, twice))

    assert says(saved, imports.counted(2, 0, 0, 0))


SAME_TWICE: Final = [
    "correct:course",
    "correct:title",
    "correct:instruction:0",
    "correct:due",
    "correct:assigned",
    *(f"answer:{kind}" for kind in TWICE_ANSWERS),
    "none",
    "empty",
]
"""The screenshot review's family answers of one value: each box of a formal card's "Correct what
was read", each answer asked with more than one option, "No assigned date was given" and a marked
box's explicit empty choice."""


def answers_now(browser: TestClient, draft_id: str) -> list[tuple[str, str, str]]:
    """The answers a draft holds by kind, subject and value, or none once a save has taken it. A
    name answer's subject is keyed by its settings, so it is left out."""
    student = state_of(browser).project_state.student_id()
    tables = state_of(browser).project_state.draft_for_save(student, draft_id)
    if tables is None:
        return []
    return sorted(
        (kind, "" if kind == "name" else subject, value)
        for (kind, subject), (value, _) in tables.answers.items()
    )


OPENED_AND_TYPED_ONCE: Final[dict[str, str]] = {
    "correct:course": "Typed once",
    "correct:title": "Typed once",
    "correct:instruction:0": "Typed once",
    "correct:due": "2026-10-12",
    "correct:assigned": "2026-10-12",
    "none": "none",
}
"""The families ``same_twice_post`` answers in a closed card it opens first ("Correct what was
read"), each with the value typed, or for "No assigned date was given" the value chosen."""


def same_twice_post(
    browser: TestClient,
    monkeypatch: pytest.MonkeyPatch,
    family: str,
    *,
    opened_and_typed: str | None,
) -> tuple[str, list[tuple[str, str]], tuple[str, str]]:
    """A review's draft, its Save post giving an answer of this family once, and that answer. A
    family answered in a closed card is given in it once the card is opened, ``opened_and_typed``
    the value given; a family given a value it does not take, or none it needs, fails the test."""
    if opened_and_typed != OPENED_AND_TYPED_ONCE.get(family):
        pytest.fail(
            f"the {family!r} answer was given opened_and_typed={opened_and_typed!r}, and it "
            f"opens and gives {OPENED_AND_TYPED_ONCE.get(family)!r}",
            pytrace=False,
        )
    if family.startswith("answer:"):
        kind = family.removeprefix("answer:")
        draft_id, page, name = asked_with_two_options(browser, monkeypatch, kind)
        value = options_of(page, name)[0][0]
        fields = page_post(page, "save", choose={name: value}, tick=units_on(page))
        return draft_id, fields, (name, value)
    if family == "empty":
        draft_id, page, name, values = open_field(browser, monkeypatch, "note-due")
        fields = page_post(page, "save", tick=units_on(page))
        conflict = send(browser, draft_id, posted_twice(fields, name, values, False)).text
        empty = f"empty:{name.removeprefix('correct:')}"
        chosen = page_post(conflict, "save", choose={empty: "empty"}, tick=units_on(conflict))
        return draft_id, chosen, (empty, "empty")
    draft_id, page = read_review(browser, monkeypatch, (RED, homework_answer()))
    page = answered(browser, draft_id, page)
    if family == "none":
        name = none_given(page)
        cards = import_review_cases.closed_cards(review_form(page), {}, [name])
        page = import_review_cases.open_cards(browser, draft_id, page, cards)
        fields = page_post(page, "save", choose={name: "none"}, tick=units_on(page))
        return draft_id, fields, (name, "none")
    field = family.removeprefix("correct:")
    name = f"correct:{box_subject(page, field)}"
    value = str(opened_and_typed)
    page = opened_for_typing(browser, draft_id, page, {name: value})
    return (
        draft_id,
        page_post(page, "save", typed={name: value}, tick=units_on(page)),
        (name, value),
    )


@pytest.mark.parametrize("first", [False, True], ids=["repeat-last", "repeat-first"])
@pytest.mark.parametrize("family", SAME_TWICE)
def test_a_family_answer_sent_twice_with_the_same_value_is_one_answer(
    tmp_path: pathlib.Path, monkeypatch: pytest.MonkeyPatch, family: str, first: bool
) -> None:
    """Save with a box, an answer of one value, "No assigned date was given" or a marked box's
    explicit empty choice sent twice with the same value, as an injected duplicate submission, the
    repeat first or last in the post: one answer, so the press does exactly what it does with that
    answer sent once, and nothing is refused as sent twice or as a post that doesn't match."""
    outcomes = []
    pages = []
    for count in (1, 2):
        where = tmp_path / f"sent-{count}"
        where.mkdir()
        with here(open_settings(where)) as browser:
            draft_id, fields, repeat = same_twice_post(
                browser, monkeypatch, family, opened_and_typed=OPENED_AND_TYPED_ONCE.get(family)
            )
            # The presses before the Save are made the same way for both counts; the repeat is
            # injected into that one Save. An answer given outside a card's boxes goes on the Save
            # it is posted with, as the raw POST it is, so the repeat lands beside that answer.
            raw = family == "empty" or family.startswith("answer:")
            made = fields if raw else reviewed(browser, draft_id, fields)
            if count == 2:
                made = (
                    import_review_cases.RawPost([repeat, *made])
                    if first
                    else import_review_cases.raw_post(made, added=[repeat])
                )
                assert sorted(made).count(repeat) >= 1
            answer = import_review_cases.posted(browser, draft_id, made)
            pages.append(followed(browser, answer))
            outcomes.append(
                (answer.status_code, answered_rows(browser), answers_now(browser, draft_id))
            )

    assert outcomes[1] == outcomes[0]
    assert not says(pages[1], imports.PRESS_SAID["field_twice"])
    assert not any(says(pages[1], imports.PRESS_SAID[said]) for said in INVALID_SAID)


OPEN_FAMILIES: Final = ["title", "due", "note-due", "assigned", "destination"]
"""The fields the unchanged retry and the explicit answer are pinned for: a formal card's title,
due date and assigned date boxes, a note piece's due date box, and a destination answer."""
NOTE_WORDS: Final = "Essay due November 20. Write about your favorite book."


def open_field(
    browser: TestClient, monkeypatch: pytest.MonkeyPatch, family: str
) -> tuple[str, str, str, tuple[str, str]]:
    """A review with a field of this family: its draft, its page, the field's posted name and two
    different values its page could send for it."""
    if family == "destination":
        draft_id, page, field = asked_with_two_options(browser, monkeypatch, "destination")
        offered = [value for value, _ in options_of(page, field)]
        return draft_id, page, field, (offered[0], offered[1])
    answer = note_under("Monday 11/9/2026", NOTE_WORDS) if family == "note-due" else None
    draft_id, page = read_review(browser, monkeypatch, (RED, answer or homework_answer()))
    page = answered(browser, draft_id, page)
    field = "due" if family == "note-due" else family
    values = (
        ("Typed once", "Typed again")
        if field in ("title", "instruction:0")
        else ("2026-10-12", "2026-10-13")
    )
    return draft_id, page, f"correct:{box_subject(page, field)}", values


def empty_choice(form: str, name: str) -> str | None:
    """The label of the explicit choice beside a marked box, or None where there is none."""
    subject = name.removeprefix("correct:")
    found = re.search(
        rf'<input type="checkbox" name="empty:{re.escape(subject)}" value="empty"> <span>([^<]*)',
        form,
    )
    return None if found is None else found.group(1)


@pytest.mark.parametrize("reverse", [False, True], ids=["first-then-second", "second-then-first"])
@pytest.mark.parametrize("family", [*OPEN_FAMILIES, "instruction:0"])
def test_a_field_sent_twice_comes_back_open_marked_and_offering_its_actual_choice(
    tmp_path: pathlib.Path, monkeypatch: pytest.MonkeyPatch, family: str, reverse: bool
) -> None:
    """Save with a box or a destination sent twice with different values, as injected
    duplicate submissions, in either order: the box comes back empty with both values
    named and its mark, and beside it the box's ordinary empty meaning as an explicit choice where
    it has one; the destination comes back with its options, none chosen, required, marked."""
    with here(open_settings(tmp_path)) as browser:
        draft_id, page, name, values = open_field(browser, monkeypatch, family)
        fields = page_post(page, "save", tick=units_on(page))
        refused = send(browser, draft_id, posted_twice(fields, name, values, reverse))

    form = html.unescape(review_form(refused.text))
    assert refused.status_code == 422
    assert f'<input type="hidden" name="unresolved:{name}" value="' in form
    if family == "destination":
        radios = re.findall(rf'<input type="radio" name="{re.escape(name)}" [^>]*>', form)
        assert len(radios) >= 2
        assert all(" required" in radio and " checked" not in radio for radio in radios)
        return
    if family == "instruction:0":
        assert re.search(rf'<textarea name="{re.escape(name)}" [^>]*>\n</textarea>', form)
    else:
        assert re.search(rf'name="{re.escape(name)}" value=""', form)
    label = empty_choice(form, name)
    if family == "note-due":
        assert label == screenshot_page.SAID["empty_no_due"]
    elif family == "instruction:0":
        assert label == screenshot_page.SAID["empty_remove"]
    elif family == "assigned":
        assert label is not None
        assert label.startswith("The date as read: ")
    else:
        assert label is None


MARKED_FAMILIES: Final = ["tick", "title", "destination"]
"""A joined note's tick, a formal card's title box and a destination answer, each marked once
sent twice."""


@pytest.mark.parametrize("tamper", ["removed", "changed"])
@pytest.mark.parametrize("family", MARKED_FAMILIES)
def test_a_returned_review_whose_mark_does_not_match_its_page_is_refused_whole(
    tmp_path: pathlib.Path, monkeypatch: pytest.MonkeyPatch, family: str, tamper: str
) -> None:
    """A field sent twice comes back marked, the mark in the page's signed list; the returned
    form with that mark removed, or holding other values, is not the page that was signed: Save
    is refused whole as a post that doesn't match its page, nothing kept or saved. The explicit
    answer on the returned page then saves once."""
    with here(open_settings(tmp_path)) as browser:
        if family == "tick":
            draft_id, page = read_review(browser, monkeypatch, (RED, essay_answer()))
            page = answered(browser, draft_id, page)
            name, values = joined_field(page), ("1", "0")
        else:
            draft_id, page, name, values = open_field(browser, monkeypatch, family)
        before = (stored_answers(browser, draft_id), answered_rows(browser))
        fields = page_post(page, "save", tick=units_on(page))
        conflict = send(browser, draft_id, posted_twice(fields, name, values, False))
        returned = page_post(conflict.text, "save", tick=units_on(conflict.text))
        mark = f"unresolved:{name}"
        present = any(field == mark for field, _ in returned)
        if tamper == "removed":
            returned = import_review_cases.raw_post(returned, removed=[mark])
        else:
            other = json.dumps(["Another answer"])
            returned = import_review_cases.raw_post(returned, {mark: other})
        refused = send(browser, draft_id, returned)
        refused_page = followed(browser, refused)
        unwritten = (stored_answers(browser, draft_id), answered_rows(browser))
        typed = {name: "Typed answer"} if family == "title" else {}
        choose = {} if family == "title" else {name: "1" if family == "tick" else values[1]}
        chosen = page_post(
            conflict.text, "save", typed=typed, choose=choose, tick=units_on(conflict.text)
        )
        answered_page = followed(browser, saved_with_corrections(browser, draft_id, chosen))
        final = answered_page
        if units_on(answered_page):
            # A Save that shows an edit's effects first, or holds a group for checking, is
            # followed by the Save on the page it gives back, as a family would press it.
            again = page_post(answered_page, "save", tick=units_on(answered_page))
            final = followed(browser, saved_with_corrections(browser, draft_id, again))
        rows = answered_rows(browser)

    assert conflict.status_code == 422
    assert present
    assert refused.status_code == 303
    assert says(refused_page, imports.PRESS_SAID["save_invalid"])
    assert unwritten == before
    assert "unresolved:" not in final
    assert re.search(r"Saved: ", html.unescape(final))
    new_rows = [row for row in rows if row not in before[1]]
    assert new_rows
    assert len(new_rows) == len(set(new_rows))
    if family == "title":
        assert [row[1] for row in new_rows].count("Typed answer") == 1


def answered_rows(browser: TestClient) -> list[tuple[str, str, date | None, date | None]]:
    """Every assignment on the record by class, title, due and assigned date."""
    return sorted(
        ((a.course, a.title, a.due_date, a.assigned_on) for a in saved_rows(browser)), key=repr
    )


@pytest.mark.parametrize("reverse", [False, True], ids=["first-then-second", "second-then-first"])
@pytest.mark.parametrize("press", ["save", "keep"])
@pytest.mark.parametrize("family", OPEN_FAMILIES)
def test_a_field_sent_twice_stays_unanswered_until_the_family_answers_it(
    tmp_path: pathlib.Path,
    monkeypatch: pytest.MonkeyPatch,
    family: str,
    press: str,
    reverse: bool,
) -> None:
    """Save, or Keep these answers, with a box or a destination sent twice with different
    values, as injected duplicate submissions, in either order: refused, naming it;
    the returned form sent back unchanged is refused again, 422, the field named again and
    nothing kept or saved; an explicit answer (a typed value, the box's explicit choice, or an
    option) then keeps or saves once with exactly that answer."""
    with here(open_settings(tmp_path)) as browser:
        draft_id, page, name, values = open_field(browser, monkeypatch, family)

        def ticks(shown: str) -> list[str]:
            return units_on(shown) if press == "save" else []

        before = (stored_answers(browser, draft_id), answered_rows(browser))
        fields = page_post(page, press, tick=ticks(page))
        conflict = send(browser, draft_id, posted_twice(fields, name, values, reverse))
        retry = send(browser, draft_id, page_post(conflict.text, press, tick=ticks(conflict.text)))
        unwritten = (stored_answers(browser, draft_id), answered_rows(browser))
        subject = name.removeprefix("correct:")
        typed: dict[str, str] = {}
        choose: dict[str, str] = {}
        if family == "title":
            typed[name] = "Typed answer"
        elif family == "due":
            typed[name] = "2026-10-14"
        elif family == "destination":
            choose[name] = values[1]
        else:
            choose[f"empty:{subject}"] = "empty"
        if press == "save" and family != "destination":
            # The explicit answer corrects a box: the family presses Review changes, then Save
            # on the page that shows its effect.
            shown_effect = send(
                browser,
                draft_id,
                page_post(retry.text, "review", typed=typed, choose=choose, tick=ticks(retry.text)),
            ).text
            chosen = page_post(shown_effect, "save", tick=ticks(shown_effect))
        else:
            chosen = page_post(
                retry.text, press, typed=typed, choose=choose, tick=ticks(retry.text)
            )
        answer = send(browser, draft_id, chosen)
        answered_page = followed(browser, answer)
        final = answered_page
        if press == "save" and units_on(answered_page):
            # A Save that shows an edit's effects first, or holds a group for checking, is
            # followed by the Save on the page it gives back, as a family would press it.
            again = page_post(answered_page, "save", tick=units_on(answered_page))
            final = followed(browser, saved_with_corrections(browser, draft_id, again))
        after = (stored_answers(browser, draft_id), answered_rows(browser))
        reopened = browser.get(f"/parent/imports/{draft_id}").text

    sent = values[::-1] if reverse else values
    assert conflict.status_code == 422
    assert says(conflict.text, imports.PRESS_SAID["field_twice"])
    assert retry.status_code == 422
    assert says(retry.text, imports.PRESS_SAID["field_unanswered"])
    assert unwritten == before
    for refused in (conflict, retry):
        form = html.unescape(review_form(refused.text))
        assert f'name="unresolved:{name}"' in form
        if family == "destination":
            labels = tuple(option_label(page, name, value) for value in sent)
            assert form.count(screenshot_page.said_twice("answer_twice", labels)) == 1
        else:
            assert form.count(screenshot_page.said_twice("box_twice", sent)) == 1
    for shown in (answered_page, final, reopened):
        assert "unresolved:" not in shown
        assert not says(shown, imports.PRESS_SAID["field_unanswered"])
        assert not says(shown, imports.PRESS_SAID["field_twice"])
    assert answer.status_code != 422
    new_rows = [row for row in after[1] if row not in before[1]]
    if press == "keep":
        assert says(answered_page, imports.PRESS_SAID["answers_kept"])
        assert new_rows == []
        if family == "destination":
            assert after[0][("destination", name.split(":", 2)[2])] == values[1]
        elif family in ("title", "due"):
            assert f'value="{typed[name]}"' in html.unescape(review_form(answered_page))
        return
    assert re.search(r"Saved: |Nothing new to save", html.unescape(final))
    assert len(new_rows) == len(set(new_rows))
    if family == "title":
        assert [row[1] for row in new_rows].count("Typed answer") == 1
    elif family == "due":
        assert [row[2] for row in new_rows].count(date(2026, 10, 14)) == 1
    elif family == "note-due":
        assert [(row[1], row[2]) for row in new_rows] == [("Essay", None)]
    elif family == "assigned":
        assert date(2026, 10, 5) in {row[3] for row in new_rows}
        assert not {date(2026, 10, 12), date(2026, 10, 13)} & {row[3] for row in new_rows}


