    assert len(fields) == 2
    assert says(done, imports.counted(2, 0, 0, 0)), import_review_cases.page_text(done)
    assert sorted(row.title for row in rows if row.course in ("English 8", "Science 8")) == [
        "Lab write-up",
        "Sentence Composing",
        "Sentence Composing",
    ]


